-- Read-only catalog capture. Use an explicitly verified isolated target; never apply migrations here.
SELECT json_build_object('tables',(SELECT json_agg(t ORDER BY t.name) FROM (SELECT table_name AS name,(SELECT json_agg(json_build_object('name',column_name,'type',data_type,'nullable',is_nullable='YES','default',column_default,'maxLength',character_maximum_length,'numericPrecision',numeric_precision,'numericScale',numeric_scale) ORDER BY ordinal_position) FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name=x.table_name) AS columns FROM information_schema.tables x WHERE table_schema='public' AND table_type='BASE TABLE' AND table_name <> '__EFMigrationsHistory')t),'constraints',(SELECT json_agg(json_build_object('table',r.relname,'name',c.conname,'kind',c.contype,'definition',pg_get_constraintdef(c.oid)) ORDER BY r.relname,c.conname) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='public'),'indexes',(SELECT json_agg(json_build_object('table',tablename,'name',indexname,'definition',indexdef) ORDER BY tablename,indexname) FROM pg_indexes WHERE schemaname='public'),'triggers',(SELECT json_agg(json_build_object('table',r.relname,'definition',pg_get_triggerdef(t.oid)) ORDER BY r.relname,t.tgname) FROM pg_trigger t JOIN pg_class r ON r.oid=t.tgrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal),'migrations',(SELECT json_agg("MigrationId" ORDER BY "MigrationId") FROM "__EFMigrationsHistory"));
